  values ('ME', 'short_answer', 'Prove that ∫ sec x dx = log|sec x + tan x| + c. (3 marks)', '∫ sec x dx = ∫ sec x (sec x + tan x)/(sec x + tan x) dx = ∫ (sec²x + sec x tan x)/(sec x + tan x) dx. Let t = sec x + tan x; then dt = (sec x tan x + sec²x) dx, which is exactly the numerator. So the integral = ∫ dt/t = log|t| + c = log|sec x + tan x| + c.', null, '[{"point": "Multiply and divide by (sec x + tan x): ∫ sec x (sec x + tan x)/(sec x + tan x) dx", "marks": 1}, {"point": "Put t = sec x + tan x, dt = (sec x tan x + sec²x) dx = sec x (sec x + tan x) dx", "marks": 1}, {"point": "∫ dt/t = log|t| + c = log|sec x + tan x| + c", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
