  values ('ME', 'short_answer', 'Calculate the amount of benzoic acid (C₆H₅COOH) required for preparing 250 mL of 0.15 M solution in methanol. (3 marks)', 'Moles of benzoic acid needed = molarity x volume (L) = 0.15 x 0.250 = 0.0375 mol. Molar mass of C₆H₅COOH = (7 x 12) + (6 x 1) + (2 x 16) = 122 g/mol. Mass required = 0.0375 x 122 = 4.575 g ≈ 4.58 g, dissolved in methanol and made up to 250 mL.', null, '[{"point": "Moles = M x V = 0.15 x 0.250 = 0.0375 mol", "marks": 1}, {"point": "Molar mass C₆H₅COOH = 7(12) + 6(1) + 2(16) = 122 g/mol", "marks": 1}, {"point": "Mass = 0.0375 x 122 = 4.575 g ≈ 4.58 g", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
